  XW += x[21] * 3.9950000000000003e+01;      // AR
  XW += x[22] * 3.2042000000000002e+01;      // CH3OH
  XW += x[23] * 3.1033999999999999e+01;      // CH2OH
  XW += x[24] * 3.1033999999999999e+01;      // CH3O
  XW += x[25] * 1.6042999999999999e+01;      // CH4
