  XW += x[37] * 4.4097000000000001e+01;      // C3H8
  XW += x[38] * 4.2081000000000003e+01;      // C3H6
  XW += x[39] * 3.9057000000000002e+01;      // C3H3
  XW += x[40] * 4.0064999999999998e+01;      // P-C3H4
  XW += x[41] * 4.0064999999999998e+01;      // A-C3H4
  XW += x[42] * 4.1073000000000000e+01;      // S-C3H5
  XW += x[43] * 5.1067999999999998e+01;      // N-C4H3
  XW += x[44] * 5.6064000000000000e+01;      // C2H3CHO
