  XW += x[27] * 2.7045999999999999e+01;  // C2H3
  XW += x[28] * 2.8053999999999998e+01;  // C2H4
  XW += x[29] * 2.9061999999999998e+01;  // C2H5
  XW += x[30] * 4.2036999999999999e+01;  // HCCOH
  XW += x[31] * 4.3045000000000002e+01;  // CH2CHO
  XW += x[32] * 4.4052999999999997e+01;  // CH3CHO
  XW += x[33] * 2.6037999999999997e+01;  // H2C2
  XW += x[34] * 4.5061000000000000e+01;  // C2H5O
  XW += x[35] * 4.3088999999999999e+01;  // N-C3H7
  XW += x[36] * 3.0070000000000000e+01;  // C2H6
  XW += x[37] * 4.4097000000000001e+01;  // C3H8
  XW += x[38] * 4.2081000000000003e+01;  // C3H6
  XW += x[39] * 3.9057000000000002e+01;  // C3H3
  XW += x[40] * 4.0064999999999998e+01;  // P-C3H4
  XW += x[41] * 4.0064999999999998e+01;  // A-C3H4
