    k_f * (kc_fast ? (ge[3] * inv_ge[16] * ge[119] * inv_ge[117])
                   : exp(-(g_RT[3] - g_RT[16] - g_RT[117] + g_RT[119])));
  // reaction 1048:  FLTN + OH => A3 + HCCO
  k_f = 0.00022 * exp((3.25) * logT - (2813.15225551476) * invT);
