                       (10.89) * sc[5] + (1.18) * sc[6] +
                       (0.0900000000000001) * sc[9] + (-0.6) * sc[21];
    const amrex::Real redP = Corr / k_f * 63300000 * exp(-1.4 * logT);
    const amrex::Real F = redP / (1.0 + redP);
