  dqdc[155] = dcdc_fac;
  dqdc[156] = dcdc_fac;
  dqdc[157] = dcdc_fac;
  for (int k = 0; k < 158; k++) {
    J[159 * k + 0] -= dqdc[k];
    J[159 * k + 1] -= dqdc[k];
    J[159 * k + 7] += dqdc[k];
  }
  J[25122] -= dqdT; // dwdot[H]/dT
  J[25123] -= dqdT; // dwdot[O2]/dT
  J[25129] += dqdT; // dwdot[HO2]/dT

  // reaction 13: 2 OH (+M) <=> H2O2 (+M)
  // a third-body and pressure-fall-off reaction
  // 3-body correction factor
  alpha = mixture + sc[4] + (12 - 1) * sc[5] + (3.6 - 1) * sc[6] +
          (1.75 - 1) * sc[9] + (0.7 - 1) * sc[21] + sc[25] + (3 - 1) * sc[36];
  // forward
  phi_f = (sc[3] * sc[3]);
  k_f = 111000000 * exp(-0.37 * logT);
  dlnkfdT = -0.37 * invT;
  // pressure-fall-off
  k_0 = 2.01e+17 * exp(-0.58 * logT - (-1153.40782319102) * invT);
  Pr = 1e-12 * alpha / k_f * k_0;
  fPr = Pr / (1.0 + Pr);
  dlnk0dT = -0.58 * invT + (-1153.40782319102) * invT2;
  dlogPrdT = log10e * (dlnk0dT - dlnkfdT);
  dlogfPrdT = dlogPrdT / (1.0 + Pr);
  // Troe form
  logPr = log10(Pr);
  Fcent1 = (1. - 0.7346) * exp(-T / 94);
  Fcent2 = 0.7346 * exp(-T / 1756);
  Fcent3 = exp(-5182 * invT);
  Fcent = Fcent1 + Fcent2 + Fcent3;
